<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref } from 'vue';import { biApi,type BiDashboard } from '@/api/bi';import BiChart from '@/components/reports/BiChart.vue';
const data=ref<BiDashboard|null>(null);let timer:number|undefined;async function load(){data.value=await biApi.screen();}onMounted(()=>{void load();timer=window.setInterval(load,30000);});onBeforeUnmount(()=>window.clearInterval(timer));
const cards=computed(()=>{const m=data.value?.metrics??{};return[['实时销售额',m.today_sales,'¥'],['实时订单',m.today_orders,''],['今日采购',m.today_purchase_amount,'¥'],['今日利润',m.today_profit,'¥'],['库存预警',m.inventory_warning,''],['待售后',m.pending_after_sales,''],['待配送',m.pending_delivery,''],['配送中',m.delivering,'']];});
</script>
<template><section class="big-screen"><header><div><b>鲜链云</b><span>水果 B2B 供应链</span></div><h1>经营数据大屏</h1><time>{{new Date(data?.generated_at??Date.now()).toLocaleString()}} · 每30秒刷新</time></header><div class="screen-metrics"><article v-for="x in cards" :key="String(x[0])"><span>{{x[0]}}</span><strong>{{x[2]}}{{Number(x[1]??0).toLocaleString()}}</strong></article></div><main><article class="screen-panel trend"><h3>近30天销售趋势</h3><BiChart :rows="data?.trends.sales??[]" type="area" value-key="sales_amount"/></article><article class="screen-panel"><h3>商品销量 TOP10</h3><BiChart :rows="data?.products??[]" type="ranking" value-key="sales_amount"/></article><article class="screen-panel"><h3>客户 TOP10</h3><BiChart :rows="data?.customers??[]" type="ranking" value-key="sales_amount"/></article><article class="screen-panel"><h3>配送状态</h3><BiChart :rows="Object.entries(data?.deliveries??{}).map(([label,value])=>({label,value}))" type="donut"/></article></main></section></template>
